/**
 * Scaffolds skills into target project directory under .agents/skills/<skill-name>/SKILL.md
 */
function scaffoldSkillsToProject(projectRoot, skillIds = []) {
  if (!projectRoot || !fs.existsSync(projectRoot)) return [];
  const skillsDir = path.join(projectRoot, ".agents", "skills");
  if (!fs.existsSync(skillsDir)) {
    fs.mkdirSync(skillsDir, { recursive: true });
  }

  const all = getAllSkills(projectRoot);
  const written = [];
  for (const skillId of skillIds) {
    const meta = all[skillId] || OFFICIAL_SKILLS[skillId];
    if (!meta) continue;

    const skillFolder = path.join(skillsDir, skillId);
    if (!fs.existsSync(skillFolder)) {
      fs.mkdirSync(skillFolder, { recursive: true });
    }

    const skillFilePath = path.join(skillFolder, "SKILL.md");
    if (!fs.existsSync(skillFilePath)) {
      fs.writeFileSync(skillFilePath, meta.content, "utf8");
    }
    written.push({ id: skillId, path: path.relative(projectRoot, skillFilePath) });
  }

  ensureSkillScripts(projectRoot, skillIds);
  return written;
}

// Helper scripts some skills run from the project (python3 scripts/<file>), shipped with the package
const SKILL_SCRIPTS = {
  "read-jira": ["read_jira.py"],
  "read-confluence": ["read_confluence.py"],
};

/**
 * Copies the helper scripts (and .env.example) that the given skills need into the project,
 * without overwriting files the project already has. Returns the files it added.
 */
function ensureSkillScripts(projectRoot, skillIds = []) {
  const packageRoot = path.join(__dirname, "..");
  const added = [];
  const copyIfMissing = (from, to) => {
    if (fs.existsSync(to) || !fs.existsSync(from) || path.resolve(from) === path.resolve(to)) return;
    fs.mkdirSync(path.dirname(to), { recursive: true });
    fs.copyFileSync(from, to);
    added.push(path.relative(projectRoot, to));
  };
  const needed = [...new Set(skillIds.flatMap((id) => SKILL_SCRIPTS[id] || []))];
  if (!projectRoot || !needed.length) return added;
  try {
    for (const file of needed) copyIfMissing(path.join(packageRoot, "scripts", file), path.join(projectRoot, "scripts", file));
    copyIfMissing(path.join(packageRoot, ".env.example"), path.join(projectRoot, ".env.example"));
  } catch (e) {
    console.warn(`[Skills] Could not add skill scripts: ${e.message}`);
  }
  return added;
}

module.exports = {
  OFFICIAL_SKILLS,
  TEAM_TEMPLATES,
  getProjectSkills,
  getAllSkills,
  saveSkillFile,
  scaffoldSkillsToProject,
  ensureSkillScripts,
};
